import{_ as a,a as n,c as t,ac as i}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第一册：英语初阶 · Lesson 34 What are they doing?","description":"学习 现在进行时复数，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 34 What are they doing?","description":"学习 现在进行时复数，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 现在进行时复数，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 33 A fine day","link":"/life/english/new-concept/book-1/unit-02/lesson-033"},"next":{"text":"第一册：英语初阶 · Lesson 35 Our village","link":"/life/english/new-concept/book-1/unit-02/lesson-035"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 33 A fine day","link":"/life/english/new-concept/book-1/unit-02/lesson-033"},"next":{"text":"第一册：英语初阶 · Lesson 35 Our village","link":"/life/english/new-concept/book-1/unit-02/lesson-035"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-02/lesson-034.md","filePath":"life/english/new-concept/book-1/unit-02/lesson-034.md"}'),o={name:"life/english/new-concept/book-1/unit-02/lesson-034.md"};function r(l,e,s,d,h,c){return n(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="第一册-英语初阶-·-lesson-34-what-are-they-doing" tabindex="-1">第一册：英语初阶 · Lesson 34 What are they doing? <a class="header-anchor" href="#第一册-英语初阶-·-lesson-34-what-are-they-doing" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 34 What are they doing?&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-02/overview">单元 2</a> · <a href="/life/english/new-concept/book-1/unit-02/lesson-033">配套课 Lesson 33</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>观察户外多人活动 本课要掌握现在进行时复数，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。本课将前一课的结构迁移到另一个例子；请先口头作答，再写出完整句子，不只替换单个单词。</p><p>本课为配套句型训练；先回顾相邻奇数课，再独立完成本页的原创练习。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>shine</td><td>/ʃaɪn/</td><td>v.</td><td>照耀</td><td>the sun shines</td></tr><tr><td>cloud</td><td>/klaʊd/</td><td>n.</td><td>云</td><td>white clouds</td></tr><tr><td>swim</td><td>/swɪm/</td><td>v.</td><td>游泳</td><td>swim in a pool</td></tr><tr><td>walk</td><td>/wɔːk/</td><td>v.</td><td>走</td><td>walk along the path</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>be swimming — 正在游泳</li><li>walk along — 沿着走</li></ul><h2 id="语法讲解-现在进行时复数" tabindex="-1">语法讲解：现在进行时复数 <a class="header-anchor" href="#语法讲解-现在进行时复数" aria-label="Permalink to &quot;语法讲解：现在进行时复数&quot;">​</a></h2><p>复数主语搭配 are + 动词 ing。what are they doing 询问活动，不问职业。并列两个动作且主语相同时可共享 be，如 They are singing and dancing。run、swim 等短元音加单辅音结尾的动词通常双写尾辅音加 ing；walk、read 不需要双写。用 now 强调当前场景。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Two dogs are running across the field.</p></blockquote><p>两只狗正在跑过田野。</p><p>Two dogs 是复数主语；run 双写 n 后加 ing，are running 构成进行时；across the field 表横穿田野。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>swim 的 ing 形式是 swimming；不要写 swiming。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“Two dogs are running across the field.”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Two dogs are running across the field. The children are drawing by the pond.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“观察户外多人活动”写两至三句，再读给同伴听。至少使用一次现在进行时复数，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>Two dogs 是复数主语；run 双写 n 后加 ing，are running 构成进行时；across the field 表横穿田野。 The children 是复数主语，are drawing 表示现在正在进行的动作；by the pond 表在池塘旁边。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>把 run 改成 ing 形式。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> running</p><p><strong>解析：</strong> 按本课规则判断：复数主语搭配 are + 动词 ing。what are they doing 询问活动，不问职业。并列两个动作且主语相同时可共享 be，如 They are singing and dancing。run、swim 等短元音加单辅音结尾的动词通常双写尾辅音加 ing；walk、read 不需要双写。用 now 强调当前场景。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“两只狗正在跑过田野。”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Two dogs are running across the field.</p><p><strong>解析：</strong> Two dogs 是复数主语；run 双写 n 后加 ing，are running 构成进行时；across the field 表横穿田野。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：The children are drawing by the pond.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 孩子们正在池塘边画画。</p><p><strong>解析：</strong> The children 是复数主语，are drawing 表示现在正在进行的动作；by the pond 表在池塘旁边。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：现在进行时复数。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-033">上一课</a> · <a href="/life/english/new-concept/book-1/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-02/lesson-035">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const g=a(o,[["render",r]]);export{p as __pageData,g as default};
